// neverError above means a rejected delete lands here as a normal item instead of
// throwing. A successful Chatwoot delete typically responds with the (now soft-deleted)
// message object and a 200, or a 204 with no body — either way, absence of an error
// shape means success. Not verified against a live call from this account.
const resp = $input.first().json;
const errText = Array.isArray(resp.errors) ? resp.errors.join(', ') : resp.error;
if (errText) {
  return [{ json: { error: String(errText) } }];
}
return [{ json: { ok: true } }];
